(function(){
 'use strict';
 // Keep the disclosure local to the selected card, including after the workout view is rebuilt.
 const workoutContent = document.getElementById('workoutStudentContent');
 if(workoutContent){
  const addSelectedPlanDisclosure = () => {
   const card = workoutContent.querySelector(':scope > .workout-plan-selector');
   const title = card?.querySelector(':scope > h4');
   const selected = card?.querySelector(':scope > .workout-plan-selected');
   const download = card?.querySelector(':scope > .ap-workout-download');
   if(!title || !selected || !download)return;

   const details = document.createElement('details');
   details.className = 'ap-selected-plan';
   const summary = document.createElement('summary');
   const label = document.createElement('span');
   label.textContent = title.textContent;
   summary.append(label);
   summary.insertAdjacentHTML('beforeend', '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>');
   const heading = document.createElement('div');
   heading.className = 'ap-selected-plan-heading';
   heading.append(selected, download);
   title.remove();
   details.append(summary, heading, ...card.childNodes);
   card.append(details);
  };
  new MutationObserver(addSelectedPlanDisclosure).observe(workoutContent, {childList: true});
  addSelectedPlanDisclosure();
 }
 let busy=false;
 const account=()=>window.APaccounts||window.parent?.APaccounts;
 const sync=()=>window.APWorkoutSync||window.parent?.APWorkoutSync;
 const current=(sid,pid,uid)=>account()?.isTeacher()===true&&account()?.teacherUid?.()===uid&&currentWorkoutPlan()?.id===pid&&currentWorkoutPlan()?.studentId===sid&&workoutStudentId===sid;
 function prescriptions(plan){
  const out={};for(const day of plan.days||[])for(const original of day.exercises||[]){
   const group=window.workoutBisetGroups?.(day).find(g=>g.exerciseIds.includes(original.id)),ex=group?window.workoutBisetExercisePrescription(day,group,original):original,tech=window.workoutTechniquePrescription?.(ex),count=group?.rounds||tech?.rows.reduce((n,r)=>n+r.sets,0)||Number(ex.sets);
   const rows=Number.isInteger(count)&&count>0&&count<=100?Array.from({length:count},(_,i)=>{const r=window.workoutTechniqueRoundPrescription?.(ex,i+1,count);return {round:i+1,reps:r?.reps??ex.reps,load:r?.load??ex.load,rest:group?(group.exerciseIds[0]===ex.id?'Sem pausa':group.restSeconds+' s'):r?.restSeconds!==undefined?r.restSeconds+' s':ex.rest}}):[];
   out[JSON.stringify([day.id,original.id])]={sets:Number.isInteger(count)&&count>0?count:ex.sets,reps:ex.reps,load:ex.load,rest:group?(group.exerciseIds[0]===ex.id?'Sem pausa':group.restSeconds+' s'):ex.rest,technique:tech?.name,notes:tech?.observations,rows};
  }return out;
 }
 window.downloadSelectedWorkout=async function(button){
  if(busy)return;
  const p=currentWorkoutPlan(),s=studentById(p?.studentId),uid=account()?.teacherUid?.();
  if(!p||!s||!uid||!current(s.id,p.id,uid))return toast('Entre como professor e selecione a ficha do aluno.');
  const selectedUid=s.firebaseUid||'';busy=true;button?.setAttribute('aria-busy','true');if(button)button.disabled=true;
  try{
   toast('Preparando a ficha para download…');
   let phoneStatus='Registros do aplicativo: aluno sem conta vinculada.',phone=[];const source=sync();
   if(selectedUid&&source){
    try{await source.refresh(selectedUid);phoneStatus='Registros do aplicativo: '+(source.summary(selectedUid)?.message||'consulta concluída.')}
    catch(_){phoneStatus='Registros do aplicativo: não foi possível consultar agora. Foram usados somente os registros já recebidos neste aparelho.'}
    phone=source.records(selectedUid);
   }else if(selectedUid)phoneStatus='Registros do aplicativo: consulta indisponível neste aparelho.';
   if(!current(s.id,p.id,uid)||(studentById(s.id)?.firebaseUid||'')!==selectedUid)throw Error('A seleção ou a conta mudou. Abra a ficha desejada e tente novamente.');
   const plan=JSON.parse(JSON.stringify(currentWorkoutPlan())),student=studentById(s.id);
   const text=APWorkoutExportModel.build({student,plan,executions:state.workoutExecutions,phoneRecords:phone,observations:state.workoutExerciseNotes,prescriptions:prescriptions(plan),phoneStatus});
   const slug=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,35)||'Treino';
   const now=new Date(),localDate=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
   const filename='Treino_'+slug(student.name)+'_'+slug(plan.name)+'_'+localDate+'.txt',bytes=new TextEncoder().encode('\uFEFF'+text);
   if(window.Android&&typeof Android.saveBase64File==='function'){
    const result=Android.saveBase64File(filename,'text/plain',workoutImportBytesToBase64(bytes));if(result===false)throw Error('Não foi possível solicitar o salvamento.');
    toast('Arquivo preparado. Aguarde a confirmação do Android em Downloads/Agenda Personal.');
   }else{const url=URL.createObjectURL(new Blob([bytes],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Ficha TXT preparada para download.');}
  }catch(e){toast(e.message||'Não foi possível exportar a ficha.',7500)}
  finally{busy=false;button?.removeAttribute('aria-busy');if(button)button.disabled=false;}
 };
})();

(function(){
 'use strict';

 const dayNames=['Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado','Domingo'];
 const dateRange=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit'});
 const sheetId='workoutStudentDialog';
 const refreshInterval=120000;
 let lastRequest=null;

 function timestamp(value){
  if(typeof value==='number')return value>0&&Number.isFinite(value)?value:NaN;
  return typeof value==='string'&&value.includes('T')?Date.parse(value):NaN;
 }

 function attendedDates(studentId,teacherRecords,studentRecords){
  const dates=new Set();
  for(const record of teacherRecords){
   if(record?.studentId!==studentId||!Array.isArray(record.exercises)||!record.exercises.length)continue;
   if(!validWorkoutDate(record.date))continue;
   const start=timestamp(record.startedAt),end=timestamp(record.finishedAt);
   const hasClock=Number.isFinite(start)&&Number.isFinite(end)&&start<=end;
   // Keep dates explicitly set by the teacher. For timed workouts use the day the session began.
   dates.add(hasClock&&record.date===iso(new Date(end))?iso(new Date(start)):record.date);
  }
  for(const record of studentRecords){
   if(!Array.isArray(record?.exerciseRecords)||!record.exerciseRecords.some(exercise=>Array.isArray(exercise?.done)&&exercise.done.includes(true)))continue;
   const start=timestamp(record.startedAt),end=timestamp(record.finishedAt);
   if(!Number.isFinite(start)||!Number.isFinite(end)||end<start)continue;
   dates.add(iso(new Date(start)));
  }
  return dates;
 }

 function currentTarget(){
  const target=document.querySelector('#workoutStudentContent .workout-sheet-trainings-heading');
  const student=workoutStudentId&&studentById(workoutStudentId);
  if(!target||!student)return null;
  return {target,student,host:window.parent.APaccounts?window.parent:window};
 }

 function paint(){
  const view=currentTarget();
  if(!view)return;
  const {target,student,host}=view;
  const linked=student.firebaseUid&&host.APaccounts?.isTeacher()===true;
  const remote=linked?host.APWorkoutSync?.records(student.firebaseUid)||[]:[];
  const dates=attendedDates(student.id,state.workoutExecutions||[],remote);
  const today=dateOnlyNow(),todayKey=iso(today),monday=new Date(today);
  monday.setDate(today.getDate()-(today.getDay()+6)%7);
  const week=dayNames.map((name,index)=>{
   const date=new Date(monday);
   date.setDate(monday.getDate()+index);
   const key=iso(date);
   return {date,name,done:dates.has(key),today:key===todayKey};
  });
  const count=week.filter(day=>day.done).length;
  const content=`<div class="ap-workout-attendance-head"><h5 id="apWorkoutAttendanceTitle">Frequência de treinos</h5><span>${dateRange.format(week[0].date)} – ${dateRange.format(week[6].date)}</span></div>
    <ul class="ap-workout-attendance-week" aria-label="Segunda a domingo">${week.map(day=>{
     const status=day.done?'Treinou':'Sem treino registrado';
     const current=day.today?' aria-current="date"':'';
     return `<li class="${day.done?'is-present':''}"${current}><span class="ap-workout-attendance-circle" aria-hidden="true">${day.done?'✓':''}</span><span aria-hidden="true">${day.name[0]}</span><span class="ap-workout-attendance-sr">${day.name}, ${dateRange.format(day.date)}. ${status}.</span></li>`;
    }).join('')}</ul><p class="ap-workout-attendance-count">${count} ${count===1?'dia com treino':'dias com treino'}</p>`;
  let card=document.getElementById('apWorkoutAttendance');
  if(!card){
   card=document.createElement('section');
   card.id='apWorkoutAttendance';
   card.setAttribute('aria-labelledby','apWorkoutAttendanceTitle');
   target.after(card);
  }
  if(card.innerHTML!==content)card.innerHTML=content;
 }

 async function refresh(){
  const view=currentTarget();
  if(!view||document.hidden||!document.getElementById(sheetId)?.classList.contains('open'))return;
  const {host,student}=view,uid=student.firebaseUid;
  if(!uid||host.APaccounts?.isTeacher()!==true||navigator.onLine===false)return;
  const owner=host.APaccounts.teacherUid?.();
  if(!owner)return;
  const key=JSON.stringify([owner,student.id,uid]);
  if(lastRequest?.key===key&&Date.now()-lastRequest.at<refreshInterval)return;
  lastRequest={key,at:Date.now()};
  try{
   const sync=host.APWorkoutSync||await host.APloadWorkoutSync?.();
   const selected=currentTarget()?.student;
   if(host.APaccounts?.teacherUid?.()===owner&&selected?.id===student.id&&selected.firebaseUid===uid){
    await sync?.refresh(uid);
   }
  }catch(_){
   // Existing local records remain available when synchronization fails.
  }finally{
   paint();
  }
 }

 const render=renderWorkoutStudent;
 renderWorkoutStudent=function(...args){
  const result=render.apply(this,args);
  paint();
  queueMicrotask(refresh);
  return result;
 };
 const open=openWorkoutStudent;
 openWorkoutStudent=function(...args){
  lastRequest=null;
  return open.apply(this,args);
 };
 function updateVisible(){
  if(document.hidden||!document.getElementById(sheetId)?.classList.contains('open'))return;
  paint();
  refresh();
 }
 addEventListener('focus',updateVisible);
 addEventListener('online',()=>{
  lastRequest=null;
  updateVisible();
 });
 document.addEventListener('visibilitychange',updateVisible);
 setInterval(updateVisible,refreshInterval);
})();

.workout-plan-selector{position:relative}.workout-plan-selector>.workout-plan-selected,.workout-plan-selector>h4{padding-right:58px}.ap-workout-download{position:absolute;right:14px;top:14px;display:grid;place-items:center;width:46px;height:46px;min-width:46px;min-height:46px;padding:10px!important;border-radius:12px}.ap-workout-download>svg{width:24px;height:24px;flex:none}.ap-workout-download[aria-busy=true]{opacity:.55;cursor:progress}@media(max-width:340px){.ap-workout-download{right:10px;top:10px}}
#apWorkoutAttendance{box-sizing:border-box;margin:12px 0 16px;padding:12px;border:1px solid var(--ac-line,var(--line));border-radius:12px;background:var(--ac-surface,var(--panel));color:var(--ac-text,var(--text))}
#apWorkoutAttendance .ap-workout-attendance-head{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;column-gap:12px;row-gap:4px}
#apWorkoutAttendance h5{margin:0;font-size:calc(.86rem * var(--ap-ts,1));font-weight:700;line-height:1.35}
#apWorkoutAttendance .ap-workout-attendance-head>span,#apWorkoutAttendance .ap-workout-attendance-count{color:var(--ac-muted,var(--muted));font-size:calc(.73rem * var(--ap-ts,1));line-height:1.4;font-variant-numeric:tabular-nums}
#apWorkoutAttendance .ap-workout-attendance-count{margin:8px 0 0}
#apWorkoutAttendance .ap-workout-attendance-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;margin:12px 0 0;padding:0;list-style:none}
#apWorkoutAttendance li{display:grid;justify-items:center;gap:5px;color:var(--ac-muted,var(--muted));font-size:calc(.74rem * var(--ap-ts,1));font-weight:650;line-height:1.2}
#apWorkoutAttendance .ap-workout-attendance-circle{box-sizing:border-box;display:grid;place-items:center;inline-size:clamp(19px,6vw,31px);aspect-ratio:1;border:1.5px solid var(--ac-muted,var(--muted));border-radius:50%;line-height:1}
#apWorkoutAttendance li[aria-current=date]{color:var(--ac-accent,var(--purple));font-weight:800}
#apWorkoutAttendance li[aria-current=date] .ap-workout-attendance-circle{border-color:var(--ac-accent,var(--purple))}
#apWorkoutAttendance li.is-present .ap-workout-attendance-circle{border-color:var(--ac-good,var(--green));color:var(--ac-good,var(--green));font-size:1rem;font-weight:800}
#apWorkoutAttendance li.is-present[aria-current=date] .ap-workout-attendance-circle{outline:1px solid var(--ac-accent,var(--purple));outline-offset:2px}
#apWorkoutAttendance .ap-workout-attendance-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}


#workoutStudentContent .ap-selected-plan > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
  list-style: none;
  border-radius: 8px;
  color: var(--ac-text, #f4ecf8);
  font-size: calc(.85rem * var(--ap-ts, 1));
  font-weight: 650;
  cursor: pointer;
}
#workoutStudentContent .ap-selected-plan > summary::-webkit-details-marker { display: none; }
#workoutStudentContent .ap-selected-plan > summary:focus-visible {
  outline: 2px solid var(--ac-accent, #cda3de);
  outline-offset: 2px;
}
#workoutStudentContent .ap-selected-plan > summary svg {
  width: 18px;
  height: 18px;
  flex: none;
  color: var(--ac-accent, #cda3de);
}
#workoutStudentContent .ap-selected-plan[open] > summary svg { transform: rotate(180deg); }
#workoutStudentContent .ap-selected-plan-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
}
#workoutStudentContent .ap-selected-plan-heading > .ap-workout-download {
  position: static;
  margin: 0;
}
